extraFoodItems.forEach(item=>{
 const base=(areaCoords[item.city]||{})[item.area]||cityCenters[item.city];
 const a=(item.id*2.399963)%(2*Math.PI),r=.0014+(item.id%7)*.0006;
 item.lat=+(base[0]+Math.sin(a)*r).toFixed(5);
 item.lng=+(base[1]+Math.cos(a)*r).toFixed(5);
 foodItems.push(item);
});
